INSERT INTO `site_settings` (`key_name`, `json_value`) VALUES ('faqs', '[{\"q\":\"InnoMIS Community’ye kimler katılabilir?\",\"a\":\"Teknoloji, girişimcilik, kariyer ve topluluk çalışmalarına ilgi duyan üniversite öğrencileri katılabilir.\"},{\"q\":\"Etkinliklere katılım ücretli mi?\",\"a\":\"Etkinliğe göre değişebilir. Duyurularda katılım koşulları açıkça belirtilir.\"},{\"q\":\"Ekiplerde görev almak mümkün mü?\",\"a\":\"Evet. Sosyal medya, etkinlik, Ar-Ge, sponsorluk, tasarım, yazılım ve operasyon ekiplerinde görev alınabilir.\"},{\"q\":\"Sponsor veya partner olarak nasıl iletişime geçilir?\",\"a\":\"İletişim formu, e-posta veya sosyal medya hesapları üzerinden toplulukla iletişime geçilebilir.\"},{\"q\":\"Etkinlik duyurularını nereden takip edebilirim?\",\"a\":\"Instagram, LinkedIn ve web sitesi üzerinden güncel duyurular takip edilebilir.\"}]');
